    if (*section.kind == "volume.rdg") return writer.add(VolumeRDG::from_section(reader, section));
    if (*section.kind == "volume.generic") return writer.add(VolumeGeneric::from_section(reader, section));
    if (*section.kind == "volume.laplacian") return writer.add(VolumeLaplacian::from_section(reader, section));
    if (*section.kind == "volume.vector") return writer.add(VolumeVector::from_section(reader, section));
    if (*section.kind == "volume.complex") return writer.add(VolumeComplex::from_section(reader, section));
    if (*section.kind == "volume.series") return writer.add(VolumeSeries::from_section(reader, section));
    if (*section.kind == "wavefunction.gto") return writer.add(WavefunctionGTO::from_section(reader, section));
    if (*section.kind == "wavefunction.bloch") return writer.add(WavefunctionBloch::from_section(reader, section));
    if (*section.kind == "basis.ao") return writer.add(BasisAO::from_section(reader, section));
    if (*section.kind == "atom_properties") return writer.add(AtomProperties::from_section(reader, section));
