    if (*section.kind == "reaction.path") return writer.add(ReactionPath::from_section(reader, section));
    if (*section.kind == "reaction.waypoints") return writer.add(ReactionWaypoints::from_section(reader, section));
    if (*section.kind == "scan.surface") return writer.add(ScanSurface::from_section(reader, section));
    if (*section.kind == "vibrations") return writer.add(Vibrations::from_section(reader, section));
    if (*section.kind == "spectra.ir") return writer.add(SpectraIR::from_section(reader, section));
    if (*section.kind == "spectra.raman") return writer.add(SpectraRaman::from_section(reader, section));
    if (*section.kind == "spectra.uvvis") return writer.add(SpectraUVVis::from_section(reader, section));
    if (*section.kind == "spectra.ecd") return writer.add(SpectraECD::from_section(reader, section));
    if (*section.kind == "spectra.vcd") return writer.add(SpectraVCD::from_section(reader, section));
