    if (*section.kind == "spectra.epr") return writer.add(SpectraEPR::from_section(reader, section));
    if (*section.kind == "spectra.generic") return writer.add(SpectraGeneric::from_section(reader, section));
    if (*section.kind == "bands") return writer.add(Bands::from_section(reader, section));
    if (*section.kind == "dos.total") return writer.add(DosTotal::from_section(reader, section));
    if (*section.kind == "dos.projected") return writer.add(DosProjected::from_section(reader, section));
    if (*section.kind == "dos.coop") return writer.add(DosCoop::from_section(reader, section));
    if (*section.kind == "dos.cohp") return writer.add(DosCohp::from_section(reader, section));
    if (*section.kind == "structure.symmetry") return writer.add(StructureSymmetry::from_section(reader, section));
    if (*section.kind == "scf_history") return writer.add(ScfHistory::from_section(reader, section));
    if (*section.kind == "citations") return writer.add(Citations::from_section(reader, section));
