    if (*section.kind == "fermi_surface") return writer.add(FermiSurface::from_section(reader, section));
    if (*section.kind == "phonon_bands") return writer.add(PhononBands::from_section(reader, section));
    if (*section.kind == "phonon_dos") return writer.add(PhononDos::from_section(reader, section));
    if (*section.kind == "topology.qtaim") return writer.add(TopologyQTAIM::from_section(reader, section));
    if (*section.kind == "run.record") return writer.add(RunRecord::from_section(reader, section));
    if (*section.kind == "job.spec") return writer.add(JobSpec::from_section(reader, section));
    if (*section.kind == "forces") return writer.add(Forces::from_section(reader, section));
    if (*section.kind == "hessian") return writer.add(Hessian::from_section(reader, section));
